def amicable_numbers_sum(limit: int) -> int:
    memo = {}
    def get_sum_of_proper_divisors(n):
        if n in memo: return memo[n]
        if n < 2:
            memo[n] = 0
            return 0
        total = 1
        for i in range(2, int(n**0.5) + 1):
            if n % i == 0:
                total += i
                if i * i != n:
                    total += n // i
        memo[n] = total
        return total

    total_sum = 0
    for a in range(1, limit + 1):
        b = get_sum_of_proper_divisors(a)
        if a != b and get_sum_of_proper_divisors(b) == a:
            total_sum += a
    return total_sum

assert amicable_numbers_sum(999) == 504
